// CloudtainerML rev0029 — Null-expert/data-sparsity MoE toy.
// Inspired by composing weight sparsity and data sparsity through zero-compute/null experts. Symbolic C++ probe.
#include <bits/stdc++.h>
using namespace std; static string q(const string&s){string o="\""; for(char c:s){ if(c=='"'||c=='\\') o+='\\'; o+=c;} return o+'"';}
struct Regime{string name; double dense_tokens, lowinfo_tokens, rare_critical, modality_gap, router_noise, load_skew;};
struct Method{string name; double active_k, null_frac, threshold, balance, rare_guard, cost_overhead; bool oracle=false;};
struct Row{string regime,method; int budget_pct; double quality,active_compute,budget_over,false_skip,load_imbalance,rare_miss,regret,score;};
int main(int argc,char**argv){string out=argc>1?argv[1]:"REV0029_NULL_EXPERT_DATA_SPARSITY_SMOKE.json"; vector<Regime> regs={{"vision_many_lowinfo",0.35,0.82,0.08,0.84,0.12,0.22},{"text_dense",0.86,0.15,0.12,0.18,0.10,0.25},{"rare_critical_lowinfo",0.40,0.65,0.92,0.56,0.25,0.35},{"noisy_router",0.55,0.44,0.34,0.40,0.72,0.28},{"imbalanced_specialists",0.62,0.30,0.48,0.50,0.22,0.88},{"mixed_multimodal",0.62,0.55,0.32,0.76,0.18,0.42}};
 vector<Method> meth={{"dense_ffn",1.0,0,0,0,0,1.0,false},{"token_choice_top2",0.50,0,0,0.25,0.08,0.52,false},{"token_choice_with_null",0.50,0.35,0.40,0.28,0.15,0.36,false},{"aggressive_null",0.35,0.55,0.62,0.20,0.05,0.24,false},{"null_plus_rare_guard",0.45,0.45,0.50,0.35,0.72,0.34,false},{"balanced_null_router",0.45,0.35,0.45,0.80,0.30,0.40,false},{"oracle_null_policy",0.40,0.55,0.70,0.90,1.0,0.30,true}};
 vector<int> budgets={25,35,50,70,100}; vector<Row> rows; map<string,int>wins,non;
 for(auto&r:regs) for(int bp:budgets){double budget=bp/100.0; vector<Row> cand; for(auto&m:meth){double skip_good=r.lowinfo_tokens*m.null_frac*(0.8+0.2*r.modality_gap); double skip_bad=max(0.0,(r.dense_tokens*0.35+r.rare_critical*0.65)*(m.null_frac+m.threshold*0.4)*(1-m.rare_guard) + r.router_noise*0.25*m.null_frac); double false_skip=min(1.0,skip_bad); double rare_miss=max(0.0,r.rare_critical*(0.65*m.null_frac+0.25*m.threshold)*(1-m.rare_guard)+0.15*r.router_noise); double load=max(0.0,r.load_skew*(1-m.balance)+0.12*m.null_frac-0.10*m.rare_guard); double active=max(0.02,m.active_k*(1-0.55*m.null_frac*r.lowinfo_tokens)+m.cost_overhead); if(m.oracle){false_skip=0.02*r.rare_critical; rare_miss=0.02*r.rare_critical; load=0.04*r.load_skew; active=min(0.42,budget+0.04);} double useful=0.88*r.dense_tokens+0.42*r.lowinfo_tokens+0.75*r.rare_critical; double quality=max(0.0,min(1.0,0.18+0.72*useful*(1-0.70*false_skip)-0.35*rare_miss-0.20*load+0.22*skip_good)); double over=max(0.0,active-budget); double score=(1-quality)+0.55*over+0.24*false_skip+0.26*rare_miss+0.15*load+0.04*active; cand.push_back({r.name,m.name,bp,quality,active,over,false_skip,load,rare_miss,0,score});}
  double best=1e9; for(auto&x:cand)best=min(best,1-x.quality); for(auto&x:cand){x.regret=max(0.0,(1-x.quality)-best); x.score+=0.10*x.regret;} auto b=min_element(cand.begin(),cand.end(),[](auto&a,auto&b){return a.score<b.score;}); wins[b->method]++; auto bn=min_element(cand.begin(),cand.end(),[](auto&a,auto&b){if(a.method=="oracle_null_policy")return false; if(b.method=="oracle_null_policy")return true; return a.score<b.score;}); non[bn->method]++; rows.insert(rows.end(),cand.begin(),cand.end());}
 ofstream f(out); f<<fixed<<setprecision(6); f<<"{\n  \"project\": \"CloudtainerML\",\n  \"revision\": \"rev0029\",\n  \"probe\": \"null_expert_data_sparsity\",\n  \"summary\": {\n    \"row_count\": "<<rows.size()<<",\n    \"primary_metric\": {\"name\": \"score\", \"direction\": \"lower_is_better\", \"winner_field\": \"method\"},\n    \"winner_counts\": {"; bool first=true; for(auto&kv:wins){if(!first)f<<", "; first=false; f<<q(kv.first)<<": "<<kv.second;} f<<"},\n    \"nonoracle_winner_counts\": {"; first=true; for(auto&kv:non){if(!first)f<<", "; first=false; f<<q(kv.first)<<": "<<kv.second;} f<<"},\n    \"interpretation\": \"Null experts are useful only when low-information tokens are common and rare-critical tokens are protected; false-skip and rare-miss fields are mandatory.\",\n    \"screen_regret_fields\": [\"active_compute\", \"budget_over\", \"false_skip\", \"load_imbalance\", \"rare_miss\", \"regret\", \"score\"]\n  },\n  \"rows\": [\n"; for(size_t i=0;i<rows.size();++i){auto&r=rows[i]; f<<"    {\"regime\": "<<q(r.regime)<<", \"method\": "<<q(r.method)<<", \"budget_pct\": "<<r.budget_pct<<", \"quality\": "<<r.quality<<", \"active_compute\": "<<r.active_compute<<", \"budget_over\": "<<r.budget_over<<", \"false_skip\": "<<r.false_skip<<", \"load_imbalance\": "<<r.load_imbalance<<", \"rare_miss\": "<<r.rare_miss<<", \"regret\": "<<r.regret<<", \"score\": "<<r.score<<"}"<<(i+1==rows.size()?"\n":",\n");} f<<"  ]\n}\n"; cerr<<"wrote "<<out<<" rows="<<rows.size()<<"\n";}
